UPDATE companies SET description='Maine Biosensors LLC, based in Dover-Foxcroft, Maine, developed the HiveSentry beehive monitoring system to give beekeepers a way to observe hive activity without traveling to distant apiaries.

Each sensor uses a pyroelectric infrared (PIR) element to detect the slight temperature rise of flying bees, reporting data every two minutes over a LoRa wireless link that can span up to half a mile. The base station displays real-time activity for up to four hives, flagging population changes, swarming, robbing, and intrusions around the clock. No internet connection is required, and installation does not alter the hive structure.

The primary customers are beekeepers managing apiaries that may be located up to a half mile from their home or workshop.

Maine Biosensors emphasizes that the sensors are completely passive, causing no disturbance to the bees, and that the long-range, stand-alone architecture eliminates the need for cellular or Wi‑Fi infrastructure at the apiary.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Beehive activity monitoring", "Pyroelectric infrared (PIR) bee detection", "LoRa long-range wireless communication", "Remote hive health monitoring", "Swarm detection", "Robbing detection", "Intrusion detection", "Multi-hive monitoring (up to 4 per base station)"], "industries": ["Beekeeping", "Apiculture", "Agriculture"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Plug-and-play system that works out of the box", "Long-range LoRa wireless link up to 1/2 mile with no internet required", "Passive PIR sensors that detect a single flying bee without disturbing the colony", "Monitors up to four hives per base station, detecting swarming, robbing, and intrusions 24/7", "Easy installation with no modifications to existing beehives"], "facts_used": ["Company name: HiveSentry, developed by Maine Biosensors LLC -> /", "Location: Dover-Foxcroft, Maine -> /", "Product: HiveSentry beehive monitoring system with sensors and base station -> /", "Technology: PIR sensor detects bee flight, LoRa wireless up to 1/2 mile -> /", "Features: plug-and-play, no internet, passive, monitors up to 4 hives, detects swarming/robbing/intrusions -> /", "Target customers: beekeepers with apiaries up to half mile away -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "The Hive Sentry system was developed by Maine Biosensors LLC. A Hive Sentry beehive monitoring system consists of one or more sensors and a base station.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='hivesentry' AND 