UPDATE companies SET description='Iron Bond Fabrication is a family-run welding and fabrication shop based in Springdale, Arkansas. The company operates a fabrication shop and a mobile service truck, serving plants, contractors, and property owners across Northwest Arkansas.

The shop focuses on four core areas: sanitary and food-grade welding for process piping, tanks, hoppers, and blenders used in food and beverage plants and breweries; structural steel fabrication of platforms, mezzanines, stair towers, catwalks, and equipment frames; mobile welding that brings on-site repair and fabrication to the customer''s plant or job site; and custom one-off metalwork such as gates, railing, brackets, trailers, and prototypes built from drawings, photos, or rough sketches. Work is performed in a small shop facility with a service truck for field jobs.

Customers include food and beverage processors, breweries, general contractors, maintenance departments, and property owners throughout Northwest Arkansas. The company has worked with firms such as Tidey Excavation and handles projects that must accommodate production schedules, sanitation windows, and plant shutdowns.

Iron Bond emphasizes that the person who quotes a job is the person who welds it, ensuring no loss of detail between estimate and finished part. The company highlights proper fit-up, purge, and heat control on every weld, straight answers on schedule and price with early notice of changes, experience working inside operating facilities, and a policy of leaving the job site as clean as they found it.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Sanitary welding", "Food-grade welding", "Process piping fabrication", "Tank and vessel fabrication", "Structural steel fabrication", "Platform fabrication", "Mezzanine fabrication", "Stair tower fabrication", "Catwalk fabrication", "Equipment frame fabrication", "Mobile welding", "On-site repair", "Field fit-up", "Custom metal fabrication", "Gate and railing fabrication", "Trailer fabrication", "Prototype fabrication", "Repair services"], "industries": ["Food and beverage", "Breweries", "General contracting", "Maintenance departments", "Property management", "Construction"], "materials": ["Stainless steel", "Structural steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["The person who quotes the job is the person who welds it", "Fit-up, purge, and heat control done properly on every weld", "Straight answers on schedule and price with early notice of changes", "Experienced working inside operating facilities around production, sanitation windows, and shutdowns", "Job site cleaned up after completion"], "facts_used": ["Location: Springdale, Arkansas -> /", "Family-run ownership -> db", "Services: sanitary welding, structural steel, mobile welding, custom fabrication -> /", "Industries: food and beverage, breweries, general contractors, maintenance departments, property owners -> /", "Customer example: Tidey Excavation -> /", "Differentiators: quoting welder, fit-up/purge/heat control, straight answers, plant-ready, cleanup -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Stainless process piping, food-grade equipment, structural steel and mobile repair \u2014 fabricated to a standard you can see in the bead.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned", "Small business"]}'::jsonb, updated_at=now() WHERE slug='iron-bond-fabrication' AND approved AND profile IS NULL;
